#include <bits/stdc++.h>
using namespace std;

string in;
size_t pos_ = 0;

void skipSpace() {
    while (pos_ < in.size() && isspace((unsigned char)in[pos_])) pos_++;
}

unsigned hex4() {
    unsigned v = stoul(in.substr(pos_, 4), nullptr, 16);
    pos_ += 4;
    return v;
}

// Parses one JSON string at pos_ into Unicode code points.
vector<unsigned> parseString() {
    vector<unsigned> out;
    pos_++;  // opening quote
    while (in[pos_] != '"') {
        unsigned char c = in[pos_];
        if (c == '\\') {
            char e = in[pos_ + 1];
            pos_ += 2;
            if (e == 'u') {
                unsigned v = hex4();
                if (v >= 0xD800 && v < 0xDC00 && in[pos_] == '\\' && in[pos_ + 1] == 'u') {
                    pos_ += 2;
                    unsigned lo = hex4();
                    v = 0x10000 + ((v - 0xD800) << 10) + (lo - 0xDC00);
                }
                out.push_back(v);
            } else {
                const char *from = "\"\\/bfnrt", *to = "\"\\/\b\f\n\r\t";
                out.push_back((unsigned char)to[strchr(from, e) - from]);
            }
        } else {
            // raw UTF-8 sequence
            int extra = c < 0x80 ? 0 : c < 0xE0 ? 1 : c < 0xF0 ? 2 : 3;
            unsigned v = extra == 0 ? c : c & (0x3F >> extra);
            for (int i = 1; i <= extra; i++) v = (v << 6) | (in[pos_ + i] & 0x3F);
            out.push_back(v);
            pos_ += extra + 1;
        }
    }
    pos_++;  // closing quote
    return out;
}

int main() {
    in.assign(istreambuf_iterator<char>(cin), istreambuf_iterator<char>());
    skipSpace();
    pos_++;  // [
    skipSpace();
    vector<unsigned> x = parseString();
    skipSpace();
    pos_++;  // ,
    skipSpace();
    vector<unsigned> y = parseString();
    int m = y.size();
    vector<int> dp(m + 1, 0);  // dp[j]: longest piece of y ending at y[j-1]
    for (unsigned c : x)
        for (int j = m; j >= 1; j--)
            if (c == y[j - 1]) dp[j] = max(dp[j], dp[j - 1] + 1);
    printf("%d\n", *max_element(dp.begin(), dp.end()));
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] in;
    static int pos;

    static void skipSpace() {
        while (pos < in.length && (in[pos] == ' ' || in[pos] == '\n' || in[pos] == '\r' || in[pos] == '\t')) pos++;
    }

    static int hex4() {
        int v = Integer.parseInt(new String(in, pos, 4), 16);
        pos += 4;
        return v;
    }

    // Parses one JSON string at pos into Unicode code points.
    static int[] parseString() {
        int[] out = new int[16];
        int size = 0;
        pos++; // opening quote
        while (in[pos] != '"') {
            int c = in[pos] & 0xFF, v;
            if (c == '\\') {
                char e = (char) in[pos + 1];
                pos += 2;
                if (e == 'u') {
                    v = hex4();
                    if (v >= 0xD800 && v < 0xDC00 && in[pos] == '\\' && in[pos + 1] == 'u') {
                        pos += 2;
                        v = Character.toCodePoint((char) v, (char) hex4());
                    }
                } else {
                    v = "\"\\/\b\f\n\r\t".charAt("\"\\/bfnrt".indexOf(e));
                }
            } else {
                // raw UTF-8 sequence
                int extra = c < 0x80 ? 0 : c < 0xE0 ? 1 : c < 0xF0 ? 2 : 3;
                v = extra == 0 ? c : c & (0x3F >> extra);
                for (int i = 1; i <= extra; i++) v = (v << 6) | (in[pos + i] & 0x3F);
                pos += extra + 1;
            }
            if (size == out.length) out = Arrays.copyOf(out, size * 2);
            out[size++] = v;
        }
        pos++; // closing quote
        return Arrays.copyOf(out, size);
    }

    public static void main(String[] args) throws IOException {
        in = System.in.readAllBytes();
        skipSpace();
        pos++; // [
        skipSpace();
        int[] x = parseString();
        skipSpace();
        pos++; // ,
        skipSpace();
        int[] y = parseString();
        int m = y.length;
        int[] dp = new int[m + 1]; // dp[j]: longest piece of y ending at y[j-1]
        for (int c : x)
            for (int j = m; j >= 1; j--)
                if (c == y[j - 1]) dp[j] = Math.max(dp[j], dp[j - 1] + 1);
        int best = 0;
        for (int v : dp) best = Math.max(best, v);
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"slices"
)

func main() {
	data, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	var pair []string
	json.Unmarshal(data, &pair)
	// compare Unicode code points, not bytes
	x, y := []rune(pair[0]), []rune(pair[1])
	m := len(y)
	dp := make([]int, m+1) // dp[j]: longest piece of y ending at y[j-1]
	for _, c := range x {
		for j := m; j >= 1; j-- {
			if c == y[j-1] {
				dp[j] = max(dp[j], dp[j-1]+1)
			}
		}
	}
	fmt.Println(slices.Max(dp))
}
